class Solution {
public:
    int minimumBeautifulSubstrings(string s) {
        unordered_set<string> pow5;
        int p = 1;
        for (int k = 0; k < 8; ++k) {
            string b = "";
            int temp = p;
            while (temp > 0) {
                b += (temp % 2 ? '1' : '0');
                temp /= 2;
            }
            reverse(b.begin(), b.end());
            pow5.insert(b);
            p *= 5;
        }
        int n = s.size();
        vector<int> dp(n + 1, 1e9);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; --i) {
            for (int j = i + 1; j <= n; ++j) {
                if (pow5.count(s.substr(i, j - i))) {
                    dp[i] = min(dp[i], 1 + dp[j]);
                }
            }
        }
        return dp[0] >= 1e9 ? -1 : dp[0];
    }
};

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

class Solution {
    public int minimumBeautifulSubstrings(String s) {
        Set<String> pow5 = new HashSet<>();
        int p = 1;
        for (int k = 0; k < 8; k++) {
            pow5.add(Integer.toBinaryString(p));
            p *= 5;
        }
        int n = s.length();
        int[] dp = new int[n + 1];
        Arrays.fill(dp, 1000);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i + 1; j <= n; j++) {
                if (pow5.contains(s.substring(i, j))) {
                    dp[i] = Math.min(dp[i], 1 + dp[j]);
                }
            }
        }
        return dp[0] >= 1000 ? -1 : dp[0];
    }
}

